action.transformation:
(
  /* get and set the id to the screen context */
  $id := $.rowData.id;
  $components.Screen.fn.setContext({"id": $id});
  $wait(500);

  /* show/hide containers */
  $components.OrderTableContainer.fn.hide();
  $components.OrderPackContainer.fn.show();

  /* refresh data using the screen context id */
  $components.OrderHeaderForm.fn.loadData();
  $components.OrderPackTable.fn.search();
  $components.OrderHuTable.fn.search()
)

