dataTransform.transform:
([
	edges.node
		~> |$|(
			$qty:= quantity.value;
			$unit := $uppercase(quantity.unit.id);
			$packQty := packedQuantity.value;
			$packUnit := $uppercase(packedQuantity.unit.id);
			$serials := orderLineRelease.pickSteps.edges.node.inventoryPickSteps.edges.node[picked = true and inventory.handlingUnitId = null].inventory.serialNumber;

			{
        "orderQuantity": $qty & " " & $unit,
				"packedQuantity": $packQty > 0 ? $packQty & " " & $packUnit : "0 " & $unit,
				"serialsToPack": $join($serials[], ", ") & ""
			}
		)|
])

